#!/usr/bin/env bash
# Regenerate agents/valkey-glide-review/config/skill.md from the glide-dev
# skill bundle: its SKILL.md followed by its reference files, with the
# leading YAML frontmatter removed from each.
#
# The bundle belongs to the Valkey skills project
# (https://github.com/valkey-io/valkey-skills). Pass the repository and
# the exact commit to build from; the generated file records both, so a
# rebuild from the same inputs gives the same file.
#
# Usage:
#   scripts/build-glide-skill.sh --repo URL_OR_CLONE --commit SHA [--path DIR] [--out FILE]
#
#   --repo    git URL of the skills repository, or a local clone of it
#             (the clone's origin URL is what the generated file records)
#   --commit  full 40-character commit SHA
#   --path    bundle directory inside the repository
#             (default: skills/glide-dev/skills/glide-dev)
#   --out     file to write (default: agents/valkey-glide-review/config/skill.md)
#
# Needs git.
set -euo pipefail

. "$(dirname "$0")/lib/common.sh"

usage() {
  echo "usage: $0 --repo URL_OR_CLONE --commit SHA [--path DIR] [--out FILE]" >&2
  exit "${1:-0}"
}

require_cmd git

REPO=""
COMMIT=""
BUNDLE_PATH="skills/glide-dev/skills/glide-dev"
OUT="$(cd "$(dirname "$0")/.." && pwd)/agents/valkey-glide-review/config/skill.md"
while [ $# -gt 0 ]; do
  case "$1" in
    --repo) [ $# -ge 2 ] || die "--repo needs a value"; REPO=$2; shift 2 ;;
    --commit) [ $# -ge 2 ] || die "--commit needs a value"; COMMIT=$2; shift 2 ;;
    --path) [ $# -ge 2 ] || die "--path needs a value"; BUNDLE_PATH=$2; shift 2 ;;
    --out) [ $# -ge 2 ] || die "--out needs a file"; OUT=$2; shift 2 ;;
    -h|--help) usage 0 ;;
    *) echo "unknown argument: $1" >&2; usage 1 ;;
  esac
done
[ -n "$REPO" ] && [ -n "$COMMIT" ] || usage 1
case "$COMMIT" in
  *[!0-9a-f]*) die "--commit must be a full lowercase commit SHA" ;;
esac
[ ${#COMMIT} -eq 40 ] || die "--commit must be a full 40-character commit SHA"

# A local clone is recorded by its origin URL, never by a path on this machine.
SOURCE_URL=$REPO
if [ -d "$REPO" ]; then
  SOURCE_URL=$(git -C "$REPO" remote get-url origin) || die "$REPO has no origin remote to record as the source"
fi

# Reference files appended after SKILL.md, in this order.
REFERENCES="core-architecture connection-internals pubsub-internals cluster-internals adding-commands build-and-test"

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

git clone -q --no-checkout "$REPO" "$WORK/src"
git -C "$WORK/src" checkout -q --detach "$COMMIT"

DIR="$WORK/src/$BUNDLE_PATH"
[ -f "$DIR/SKILL.md" ] || die "$BUNDLE_PATH/SKILL.md not found at $COMMIT"
for ref in $REFERENCES; do
  [ -f "$DIR/reference/$ref.md" ] || die "$BUNDLE_PATH/reference/$ref.md not found at $COMMIT"
done

# Print a markdown file without the frontmatter block at its top.
strip_frontmatter() {
  awk 'NR == 1 && $0 == "---" { fm = 1; next } fm && $0 == "---" { fm = 0; next } !fm' "$1"
}

{
  echo "# glide-dev: contributor reviewer knowledge"
  echo ""
  echo "Generated by scripts/build-glide-skill.sh from $BUNDLE_PATH in"
  echo "$SOURCE_URL at commit $COMMIT. Do not edit this file; rebuild it."
  echo ""
  echo "---"
  echo ""
  echo "## glide-dev SKILL.md"
  echo ""
  strip_frontmatter "$DIR/SKILL.md"
  for ref in $REFERENCES; do
    echo ""
    echo "---"
    echo ""
    echo "## Reference: $ref"
    echo ""
    strip_frontmatter "$DIR/reference/$ref.md"
  done
} > "$OUT.tmp"
mv "$OUT.tmp" "$OUT"

echo "wrote $OUT ($(wc -l < "$OUT" | tr -d ' ') lines)"
